-- Speglar det som lades på databasen 2026-09-16 via apply_migration i tre delar:
--   vq1000_order_code_from_catalogue_part_01  (backup, schema, familj, parametrar, värdelista, rensning av regler)
--   vq1000_order_code_from_catalogue_part_02  (regler 1–20)
--   vq1000_order_code_from_catalogue_part_03  (regler 21–32, dokumentkarta, produktraden döpt om)
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts vq1000):
--   regler  32   md5 25b115a5251ee7f24d10fcd1e51c0eda   villkor df854c05c54fd6699c37af4e297baca7
--   värden  39   md5 10ddd215af7f728a11022d3aee4f3cfe
--   schema       md5 dc9b08e7e4e30ceb0806f21b970dee37
-- Verifierat live: /sv/configurator/vq1000 bygger VQ1100-51 (sida 367) och VQ2100-5W1-02 på
-- underplatta (sida 403), stoppar E (utan ljus/spärrdiod) ihop med negativ common N (not 2).
--
-- VQ: beställnyckeln enligt SMC 5 Port Solenoid Valve VQ1000/2000 Series (sida 367, 371 och 403).
-- GENERERAD ur src/lib/catalog/vq.ts -- redigera inte för hand.
--
-- Rättar familjen vq1000, som hade mallen 'VQ1000-{size}-{function}-{voltage}-{connection}'
-- med påhittade värden. SMC:s kod är
-- VQ{serie}{funktion}0{tätning}{tillval}-{spänning}{ljus}{manöver}{kapsling}1-{port}{gänga}-{ce},
-- t.ex. VQ1100-51 och VQ1200-51 (sida 367) och VQ2100-5W1-02 på underplatta
-- (sida 403); nollan efter funktionen och ettan efter manövern är fasta.
-- Serien VQ2000, tätning, tillvalen B/K/N/R i bokstavsordning, sex spänningar,
-- ljus, manöver, kapsling, underplatta och CE-märkning fanns inte alls.
--
-- SMC-VQ1101N-5G döps om till SMC-VQ1101-51 (plug-in-ventilen har varken
-- port eller grommet och är pilotstyrd).

begin;

create schema if not exists backup;
create table if not exists backup.vq1000_before_20260916 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'vq1000'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'vq1000'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'vq1000';

insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-VQ1000-V1', '{"version":"1.0","steps":[{"id":"series","step":1,"title_sv":"Serie","title_en":"Series","required":true,"type":"single_select","options":[{"v":"1","label":"VQ1000 (ventilramp VV5Q11)"},{"v":"2","label":"VQ2000 (ventilramp VV5Q21 eller underplatta; IP65 möjlig)"}]},{"id":"actuation","step":2,"title_sv":"Funktion","title_en":"Type of actuation","required":true,"type":"single_select","options":[{"v":"1","label":"2-läges, enkel magnet (monostabil)"},{"v":"2","label":"2-läges, dubbel magnet (bistabil)"},{"v":"3","label":"3-läges, stängt mittläge"},{"v":"4","label":"3-läges, avluftat mittläge"},{"v":"5","label":"3-läges, trycksatt mittläge"},{"v":"A","label":"4-läges dubbel 3-portsventil, två NC (bara gummitätning)"},{"v":"B","label":"4-läges dubbel 3-portsventil, två NO (bara gummitätning)"},{"v":"C","label":"4-läges dubbel 3-portsventil, NC + NO (bara gummitätning)"}]},{"id":"seal","step":3,"title_sv":"Tätning","title_en":"Seal","required":true,"type":"single_select","options":[{"v":"0","label":"Metalltätning"},{"v":"1","label":"Gummitätning"}]},{"id":"func","step":4,"title_sv":"Tillval (standard är 0,4 W utan tillval)","title_en":"Function (standard 0.4 W without options is default)","required":false,"type":"single_select","options":[{"v":"B","label":"B: snabb respons (0,95 W)"},{"v":"K","label":"K: högtryck 1,0 MPa (0,95 W, bara metalltätning)"},{"v":"N","label":"N: negativ common"},{"v":"BN","label":"B: snabb respons (0,95 W) + N: negativ common"},{"v":"KN","label":"K: högtryck 1,0 MPa (0,95 W, bara metalltätning) + N: negativ common"},{"v":"R","label":"R: extern pilot"},{"v":"BR","label":"B: snabb respons (0,95 W) + R: extern pilot"},{"v":"KR","label":"K: högtryck 1,0 MPa (0,95 W, bara metalltätning) + R: extern pilot"},{"v":"NR","label":"N: negativ common + R: extern pilot"},{"v":"BNR","label":"B: snabb respons (0,95 W) + N: negativ common + R: extern pilot"},{"v":"KNR","label":"K: högtryck 1,0 MPa (0,95 W, bara metalltätning) + N: negativ common + R: extern pilot"}]},{"id":"voltage","step":5,"title_sv":"Spolspänning","title_en":"Coil voltage","required":true,"type":"single_select","options":[{"v":"5","label":"24 V DC"},{"v":"6","label":"12 V DC"},{"v":"1","label":"100 V AC 50/60 Hz"},{"v":"3","label":"110 V AC 50/60 Hz"},{"v":"2","label":"200 V AC 50/60 Hz (bara F/L-kit)"},{"v":"4","label":"220 V AC 50/60 Hz (bara F/L-kit)"}]},{"id":"light","step":6,"title_sv":"Ljus/spärrdiod (standard är med)","title_en":"Light/surge voltage suppressor (with is standard)","required":false,"type":"single_select","options":[{"v":"E","label":"Utan ljus/spärrdiod, opolär (standard är med; inte S-kit, inte med N)"}]},{"id":"override","step":7,"title_sv":"Manuell manöver (standard är olåst tryckknapp, verktyg)","title_en":"Manual override (non-locking push type is standard)","required":false,"type":"single_select","options":[{"v":"B","label":"Låsbar manöver, spårskruv (verktyg)"},{"v":"C","label":"Låsbar manöver, manuell"},{"v":"D","label":"Skjutlåsbar manöver, manuell"}]},{"id":"enclosure","step":8,"title_sv":"Kapsling (standard är dammskyddad)","title_en":"Enclosure (dust-protected is standard)","required":false,"type":"single_select","options":[{"v":"W","label":"IP65 dammtät och spolsäker (bara VQ2000; T/L/S/M-kit eller underplatta)"}]},{"id":"port","step":9,"title_sv":"Underplatta (enkelventil)","title_en":"Sub-plate (single unit)","required":false,"type":"single_select","options":[{"v":"02","label":"Underplatta 1/4 (enkelventil, bara VQ2000)"}]},{"id":"thread","step":10,"title_sv":"Underplattans gänga (standard är Rc)","title_en":"Sub-plate thread (Rc is standard)","required":false,"type":"single_select","options":[{"v":"N","label":"NPT-gänga på underplattan"},{"v":"T","label":"NPTF-gänga på underplattan"},{"v":"F","label":"G-gänga på underplattan (standard är Rc)"}]},{"id":"ce","step":11,"title_sv":"CE/UKCA-märkning","title_en":"CE/UKCA marking","required":false,"type":"single_select","options":[{"v":"Q","label":"CE/UKCA-märkt (bara DC)"}]}]}'::jsonb,
        'SMC VQ1000/2000 5-portsventil, plug-in eller på underplatta', 'SMC VQ1000/2000 5 port solenoid valve, plug-in or on sub-plate', 'valve')
on conflict (schema_id) do update set
  schema_json = excluded.schema_json,
  title_sv = excluded.title_sv,
  title_en = excluded.title_en;

update configurator_families set
  title = '5-portsventil VQ1000/2000, basmonterad plug-in för ventilramp (VQ2000 även på underplatta)',
  description = 'SMC VQ1000/2000 base mounted plug-in 5 port solenoid valve for the VV5Q11/VV5Q21 manifolds: 2-position single/double, 3-position and 4-position dual 3-port, metal or rubber seal, high-speed/high-pressure/negative common/external pilot options, DC or AC, IP65 and sub-plate single unit for VQ2000.',
  stroke_min_mm = null,
  stroke_max_mm = null,
  order_code_template = 'VQ{series}{actuation}0{seal}{func}-{voltage}{light}{override}{enclosure}1-{port}{thread}-{ce}',
  rules_schema_id = 'SCHEMA-VQ1000-V1'
where slug = 'vq1000';


delete from configurator_param_values v using configurator_params p, configurator_families f
  where v.param_id = p.id and p.family_id = f.id and f.slug = 'vq1000';
delete from configurator_params p using configurator_families f
  where p.family_id = f.id and f.slug = 'vq1000';

insert into configurator_params (family_id, param_key, label, param_type, sort_order, required, min_value, max_value, show_code)
select f.id, r.param_key, r.label, r.param_type, r.sort_order, r.required, r.min_value, r.max_value, true
from configurator_families f,
     jsonb_to_recordset('[{"param_key":"series","label":"Serie","param_type":"select","sort_order":1,"required":true,"min_value":null,"max_value":null},{"param_key":"actuation","label":"Funktion","param_type":"select","sort_order":2,"required":true,"min_value":null,"max_value":null},{"param_key":"seal","label":"Tätning","param_type":"select","sort_order":3,"required":true,"min_value":null,"max_value":null},{"param_key":"func","label":"Tillval (standard är 0,4 W utan tillval)","param_type":"select","sort_order":4,"required":false,"min_value":null,"max_value":null},{"param_key":"voltage","label":"Spolspänning","param_type":"select","sort_order":5,"required":true,"min_value":null,"max_value":null},{"param_key":"light","label":"Ljus/spärrdiod (standard är med)","param_type":"select","sort_order":6,"required":false,"min_value":null,"max_value":null},{"param_key":"override","label":"Manuell manöver (standard är olåst tryckknapp, verktyg)","param_type":"select","sort_order":7,"required":false,"min_value":null,"max_value":null},{"param_key":"enclosure","label":"Kapsling (standard är dammskyddad)","param_type":"select","sort_order":8,"required":false,"min_value":null,"max_value":null},{"param_key":"port","label":"Underplatta (enkelventil)","param_type":"select","sort_order":9,"required":false,"min_value":null,"max_value":null},{"param_key":"thread","label":"Underplattans gänga (standard är Rc)","param_type":"select","sort_order":10,"required":false,"min_value":null,"max_value":null},{"param_key":"ce","label":"CE/UKCA-märkning","param_type":"select","sort_order":11,"required":false,"min_value":null,"max_value":null}]'::jsonb)
       as r(param_key text, label text, param_type text, sort_order int, required boolean,
            min_value numeric, max_value numeric)
where f.slug = 'vq1000';

insert into configurator_param_values (param_id, code, label, sort_order)
select p.id, r.code, r.label, r.sort_order
from jsonb_to_recordset('[{"param_key":"series","code":"1","label":"VQ1000 (ventilramp VV5Q11)","sort_order":0},{"param_key":"series","code":"2","label":"VQ2000 (ventilramp VV5Q21 eller underplatta; IP65 möjlig)","sort_order":1},{"param_key":"actuation","code":"1","label":"2-läges, enkel magnet (monostabil)","sort_order":0},{"param_key":"actuation","code":"2","label":"2-läges, dubbel magnet (bistabil)","sort_order":1},{"param_key":"actuation","code":"3","label":"3-läges, stängt mittläge","sort_order":2},{"param_key":"actuation","code":"4","label":"3-läges, avluftat mittläge","sort_order":3},{"param_key":"actuation","code":"5","label":"3-läges, trycksatt mittläge","sort_order":4},{"param_key":"actuation","code":"A","label":"4-läges dubbel 3-portsventil, två NC (bara gummitätning)","sort_order":5},{"param_key":"actuation","code":"B","label":"4-läges dubbel 3-portsventil, två NO (bara gummitätning)","sort_order":6},{"param_key":"actuation","code":"C","label":"4-läges dubbel 3-portsventil, NC + NO (bara gummitätning)","sort_order":7},{"param_key":"seal","code":"0","label":"Metalltätning","sort_order":0},{"param_key":"seal","code":"1","label":"Gummitätning","sort_order":1},{"param_key":"func","code":"B","label":"B: snabb respons (0,95 W)","sort_order":0},{"param_key":"func","code":"K","label":"K: högtryck 1,0 MPa (0,95 W, bara metalltätning)","sort_order":1},{"param_key":"func","code":"N","label":"N: negativ common","sort_order":2},{"param_key":"func","code":"BN","label":"B: snabb respons (0,95 W) + N: negativ common","sort_order":3},{"param_key":"func","code":"KN","label":"K: högtryck 1,0 MPa (0,95 W, bara metalltätning) + N: negativ common","sort_order":4},{"param_key":"func","code":"R","label":"R: extern pilot","sort_order":5},{"param_key":"func","code":"BR","label":"B: snabb respons (0,95 W) + R: extern pilot","sort_order":6},{"param_key":"func","code":"KR","label":"K: högtryck 1,0 MPa (0,95 W, bara metalltätning) + R: extern pilot","sort_order":7},{"param_key":"func","code":"NR","label":"N: negativ common + R: extern pilot","sort_order":8},{"param_key":"func","code":"BNR","label":"B: snabb respons (0,95 W) + N: negativ common + R: extern pilot","sort_order":9},{"param_key":"func","code":"KNR","label":"K: högtryck 1,0 MPa (0,95 W, bara metalltätning) + N: negativ common + R: extern pilot","sort_order":10},{"param_key":"voltage","code":"5","label":"24 V DC","sort_order":0},{"param_key":"voltage","code":"6","label":"12 V DC","sort_order":1},{"param_key":"voltage","code":"1","label":"100 V AC 50/60 Hz","sort_order":2},{"param_key":"voltage","code":"3","label":"110 V AC 50/60 Hz","sort_order":3},{"param_key":"voltage","code":"2","label":"200 V AC 50/60 Hz (bara F/L-kit)","sort_order":4},{"param_key":"voltage","code":"4","label":"220 V AC 50/60 Hz (bara F/L-kit)","sort_order":5},{"param_key":"light","code":"E","label":"Utan ljus/spärrdiod, opolär (standard är med; inte S-kit, inte med N)","sort_order":0},{"param_key":"override","code":"B","label":"Låsbar manöver, spårskruv (verktyg)","sort_order":0},{"param_key":"override","code":"C","label":"Låsbar manöver, manuell","sort_order":1},{"param_key":"override","code":"D","label":"Skjutlåsbar manöver, manuell","sort_order":2},{"param_key":"enclosure","code":"W","label":"IP65 dammtät och spolsäker (bara VQ2000; T/L/S/M-kit eller underplatta)","sort_order":0},{"param_key":"port","code":"02","label":"Underplatta 1/4 (enkelventil, bara VQ2000)","sort_order":0},{"param_key":"thread","code":"N","label":"NPT-gänga på underplattan","sort_order":0},{"param_key":"thread","code":"T","label":"NPTF-gänga på underplattan","sort_order":1},{"param_key":"thread","code":"F","label":"G-gänga på underplattan (standard är Rc)","sort_order":2},{"param_key":"ce","code":"Q","label":"CE/UKCA-märkt (bara DC)","sort_order":0}]'::jsonb)
       as r(param_key text, code text, label text, sort_order int)
join configurator_params p on p.param_key = r.param_key
join configurator_families f on f.id = p.family_id and f.slug = 'vq1000';

delete from config_rules where schema_id = 'SCHEMA-VQ1000-V1';


insert into config_rules (schema_id, severity, if_json, message_sv, message_en, goto_step)
select 'SCHEMA-VQ1000-V1', r->>'severity', r->'if_json',
       r->>'message_sv', r->>'message_en', r->>'goto_step'
from jsonb_array_elements('[{"severity":"error","if_json":{"and":[{"in":[{"var":"actuation"},["A","B","C"]]},{"==":[{"var":"seal"},"0"]}]},"message_sv":"De 4-läges dubbla 3-portsventilerna A, B och C finns bara med gummitätning (1) (sida 367 och 371, not).","message_en":"The 4-position dual 3-port valves A, B and C exist only with the rubber seal (1) (pages 367 and 371, note).","goto_step":"vq1000-seal"},{"severity":"error","if_json":{"and":[{"in":[{"var":"func"},["K","KN","KR","KNR"]]},{"==":[{"var":"seal"},"1"]}]},"message_sv":"Högtryckstypen K (1,0 MPa) finns bara med metalltätning (0) (sida 367, not 2).","message_en":"The high-pressure type K (1.0 MPa) exists only with the metal seal (0) (page 367, note 2).","goto_step":"vq1000-func"},{"severity":"error","if_json":{"and":[{"in":[{"var":"func"},["B","K","N","BN","KN","BR","KR","NR","BNR","KNR"]]},{"in":[{"var":"voltage"},["1","3","2","4"]]}]},"message_sv":"Tillvalen B, K och N (snabb respons, högtryck, negativ common) finns bara för DC; med AC går bara standard och extern pilot R (sida 367, tabellen Function).","message_en":"The options B, K and N (high-speed response, high pressure, negative common) exist only for DC; with AC only standard and the external pilot R are available (page 367, Function table).","goto_step":"vq1000-func"},{"severity":"error","if_json":{"and":[{"in":[{"var":"func"},["R","BR","KR","NR","BNR","KNR"]]},{"in":[{"var":"actuation"},["A","B","C"]]}]},"message_sv":"Extern pilot R finns inte för de dubbla 3-portsventilerna A, B och C (sida 367, not 5).","message_en":"The external pilot R is not available for the dual 3-port valves A, B and C (page 367, note 5).","goto_step":"vq1000-func"},{"severity":"error","if_json":{"and":[{"==":[{"var":"light"},"E"]},{"in":[{"var":"func"},["N","BN","KN","NR","BNR","KNR"]]}]},"message_sv":"Utan ljus/spärrdiod (E) går inte ihop med negativ common (N): E är opolär och kan själv användas som negativ common (sida 367, not 2).","message_en":"Without light/surge voltage suppressor (E) cannot be combined with the negative common (N): E has no polarity and can itself be used as a negative common (page 367, note 2).","goto_step":"vq1000-light"},{"severity":"error","if_json":{"and":[{"==":[{"var":"enclosure"},"W"]},{"in":[{"var":"series"},["1"]]}]},"message_sv":"Kapslingen W (IP65) finns bara för VQ2000, inte VQ1000 (sida 371 och 375, not 4).","message_en":"The enclosure W (IP65) exists only for VQ2000, not VQ1000 (pages 371 and 375, note 4).","goto_step":"vq1000-enclosure"},{"severity":"error","if_json":{"and":[{"==":[{"var":"port"},"02"]},{"in":[{"var":"series"},["1"]]}]},"message_sv":"Underplattan (enkelventil) finns bara för VQ2000, inte VQ1000 (sida 403).","message_en":"The sub-plate (single unit) exists only for VQ2000, not VQ1000 (page 403).","goto_step":"vq1000-port"},{"severity":"error","if_json":{"and":[{"!=":[{"var":"thread"},""]},{"==":[{"var":"port"},""]}]},"message_sv":"Gängtypen hör till underplattan — välj underplattan 02 först (sida 403).","message_en":"The thread type belongs to the sub-plate — choose the sub-plate 02 first (page 403).","goto_step":"vq1000-thread"},{"severity":"error","if_json":{"and":[{"==":[{"var":"port"},"02"]},{"in":[{"var":"voltage"},["2","4"]]},{"==":[{"var":"enclosure"},""]}]},"message_sv":"Enkelventilen på underplatta med 200 eller 220 V AC kräver kapslingen W (IP65); standardutförandet (dammskyddat) går inte med de spänningarna (sida 403, not 2).","message_en":"The single unit on a sub-plate with 200 or 220 V AC requires the enclosure W (IP65); the standard (dust-protected) version is not compatible with those voltages (page 403, note 2).","goto_step":"vq1000-enclosure"},{"severity":"error","if_json":{"and":[{"==":[{"var":"ce"},"Q"]},{"in":[{"var":"voltage"},["1","3","2","4"]]}]},"message_sv":"CE/UKCA-märkningen Q finns bara för DC-ventilerna (sida 367, 371 och 403, not).","message_en":"The CE/UKCA marking Q exists only for the DC valves (pages 367, 371 and 403, note).","goto_step":"vq1000-ce"},{"severity":"info","if_json":{"in":[{"var":"voltage"},["2","4"]]},"message_sv":"200 och 220 V AC går bara i ventilramp med F-kit (D-sub) eller L-kit (sida 367 och 371, not).","message_en":"200 and 220 V AC are available only in a manifold with the F kit (D-sub) or L kit (pages 367 and 371, note).","goto_step":"vq1000-voltage"},{"severity":"info","if_json":{"==":[{"var":"light"},"E"]},"message_sv":"E (utan ljus/spärrdiod) går inte i ventilramp med S-kit (sida 367, not 1).","message_en":"E (without light/surge voltage suppressor) is not applicable to a manifold with the S kit (page 367, note 1).","goto_step":"vq1000-light"},{"severity":"info","if_json":{"and":[{"==":[{"var":"enclosure"},"W"]},{"==":[{"var":"port"},""]}]},"message_sv":"IP65 (W) gäller i ventilramp med T-, L-, S- eller M-kit; på underplattan är ventilen IP65 med tätad kontakt i elanslutningen (sida 371 not, 375 not 4, 403).","message_en":"IP65 (W) applies in a manifold with the T, L, S or M kit; on the sub-plate the valve is IP65 with a seal connector in the electrical entry (page 371 note, 375 note 4, 403).","goto_step":"vq1000-enclosure"},{"severity":"info","if_json":{"==":[{"var":"port"},"02"]},"message_sv":"Underplattan 1/4 kan också beställas ensam som VQ2000-PW-02 (gängbokstaven efter 02); ventilen har plintanslutning med G 3/8-ingång (sida 403).","message_en":"The sub-plate 1/4 can also be ordered alone as VQ2000-PW-02 (thread letter after 02); the valve has a terminal block with a G 3/8 entry (page 403).","goto_step":"vq1000-port"},{"severity":"info","if_json":{"in":[{"var":"func"},["R","BR","KR","NR","BNR","KNR","N","BN","KN"]]},"message_sv":"Extern pilot R och negativ common N är halvstandard — se sida 405–406 för anslutning och pilotmatning.","message_en":"The external pilot R and the negative common N are semi-standard — see pages 405–406 for wiring and pilot supply.","goto_step":"vq1000-func"},{"severity":"info","if_json":{"and":[{"==":[{"var":"series"},"1"]},{"==":[{"var":"actuat