insert into knowledge_doc_families (source_file, family_slug, doc_title)
values ('smc-kat-vq1000.pdf', 'vq1000', 'SMC — SMC 5 Port Solenoid Valve VQ1000/2000 Series')
on conflict (source_file, family_slug) do update set doc_title = excluded.doc_title;


update products set
  sku = 'SMC-VQ1101-51',
  name = 'VQ1101 5/2 monostabil, plug-in (gummitätning)',
  description = 'Base mounted plug-in 5 port solenoid valve VQ1000, 2-position single (monostable), rubber seal, 24 V DC, with light/surge voltage suppressor, non-locking push override. Ordered for the VV5Q11 manifold (cylinder ports on the manifold: ø3.2/ø4/ø6 One-touch or M5). Order code VQ1101-51 (catalogue page 367).'
where sku = 'SMC-VQ1101N-5G';

delete from product_specs s using products p
where s.product_id = p.id and p.sku = 'SMC-VQ1101-51' and s.key = 'port_size';

update product_specs s set value = '5/2 monostabil (2-läges enkel magnet), gummitätning'
from products p where s.product_id = p.id and p.sku = 'SMC-VQ1101-51' and s.key = 'function';

update product_specs s set value = '7'
from products p where s.product_id = p.id and p.sku = 'SMC-VQ1101-51' and s.key = 'max_pressure';

update product_specs s set value = '-10 to +50'
from products p where s.product_id = p.id and p.sku = 'SMC-VQ1101-51' and s.key = 'temp_range';

insert into product_specs (product_id, key, value)
select p.id, x.key, x.value
from products p
cross join lateral (values
  ('series', 'VQ1000'),
  ('mounting', 'Plug-in i ventilramp VV5Q11 (kit F/P/T/L/S/M); cylinderportar på rampen C3/C4/C6/M5'),
  ('min_pressure_mpa', '0.15'),
  ('power_w', '0.4'),
  ('flow_c', '0.85 dm³/(s·bar) 1→4/2 (gummitätning)'),
  ('order_code_example', 'VQ1101-51'),
  ('catalogue', 'SMC VQ1000/2000, How to Order Valves sida 367 (VQ1000) och 371 (VQ2000), underplatta sida 403, data sida 375')
) as x(key, value)
where p.sku = 'SMC-VQ1101-51'
  and not exists (select 1 from product_specs y where y.product_id = p.id and y.key = x.key);


commit;

